package com.smartmart.wishlist.controller; import com.smartmart.user.entity.User; import com.smartmart.wishlist.dto.WishlistResponse; import com.smartmart.wishlist.service.WishlistService; import lombok.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/wishlist") @RequiredArgsConstructor @PreAuthorize("hasRole('SHOPPER')") public class WishlistController {private final WishlistService s; @PostMapping("/{productId}") public void add(@AuthenticationPrincipal User u,@PathVariable Long productId){s.add(u,productId);}@GetMapping public List<WishlistResponse> list(@AuthenticationPrincipal User u){return s.list(u);}@DeleteMapping("/{productId}") public void remove(@AuthenticationPrincipal User u,@PathVariable Long productId){s.remove(u,productId);}}
